#ifndef __DRIVERS_SPIM_DW_HEADER_H
#define __DRIVERS_SPIM_DW_HEADER_H
#include <linux/list.h>
#include <io.h>
#include <version_autogenerated.h>

#define DMA_TRANSFER        1
#define CPU_TRANSFER        1

// QUICK_TRANSFER用于快速传输，同时可指定半双工或全双工，默认使用半双工
//#define QUICK_TRANSFER

/* SPI register offsets */
#define SPIM_CTRLR0     0x00
#define SPIM_CTRLR1     0x04
#define SPIM_ENR        0x08
#define SPIM_SER        0x10
#define SPIM_BAUDR      0x14
#define SPIM_TXFTLR     0x18
#define SPIM_RXFTLR     0x1c
#define SPIM_TXFLR      0x20
#define SPIM_RXFLR      0x24
#define SPIM_SR         0x28
#define SPIM_IMR        0x2c
#define SPIM_ISR        0x30
#define SPIM_RISR       0x34
#define DW_SPI_TXOICR   0x38
#define DW_SPI_RXOICR   0x3c
#define DW_SPI_RXUICR   0x40
#define SPIM_ICR        0x48
#define SPIM_DMACR      0x4c
#define SPIM_DMATDLR    0x50
#define SPIM_DMARDLR    0x54
#define SPIM_TXDR       0x60
#define SPIM_RXDR       0x60
#define SPIM_CS         0xf4
/* --------Bit fields in CTRLR0--------begin */
#define SPI_DFS_OFFSET           0
#define SPI_DFS_8BIT             0x07
#define SPI_DFS_16BIT            0x0F

#define SPI_FRF_OFFSET           4    /* Frame Format */
#define SPI_FRF_SPI              0x0  /* motorola spi */
#define SPI_FRF_SSP              0x1  /* Texas Instruments SSP*/
#define SPI_FRF_MICROWIRE        0x2  /*  National Semiconductors Microwire */
#define SPI_FRF_RESV             0x3

#define SPI_MODE_OFFSET          6     /* SCPH & SCOL */
#define SPI_SCPH_OFFSET          6     /* Serial Clock Phase */
#define SPI_SCPH_TOGMID          0     /* Serial clock toggles in middle of first data bit */
#define SPI_SCPH_TOGSTA          1     /* Serial clock toggles at start of first data bit */
#define SPI_SCOL_OFFSET          7     /* Serial Clock Polarity */

#define SPI_TMOD_OFFSET          8
#define SPI_TMOD_MASK            (0x3 << SPI_TMOD_OFFSET)
#define SPI_TMOD_TR              0x0   /* xmit & recv */
#define SPI_TMOD_TO              0x1   /* xmit only */
#define SPI_TMOD_RO              0x2   /* recv only */
#define SPI_TMOD_EPROMREAD       0x3   /* eeprom read mode */

#define SPI_SLVOE_OFFSET         10
#define SPI_SRL_OFFSET           11
#define SPI_CFS_OFFSET           12
/* --------Bit fields in CTRLR0--------end */
/* Bit fields in SR, 7 bits */
#define SR_MASK                 0x7f            /* cover 7 bits */
#define SR_BUSY                 (1 << 0)
#define SR_TF_NOT_FULL          (1 << 1)
#define SR_TF_EMPT              (1 << 2)
#define SR_RF_NOT_EMPT          (1 << 3)
#define SR_RF_FULL              (1 << 4)
#define SR_TX_ERR               (1 << 5)
#define SR_DCOL                 (1 << 6)
/* Bit fields in ISR, IMR, RISR, 7 bits */
#define SPI_INT_TXEI            (1 << 0)
#define SPI_INT_TXOI            (1 << 1)
#define SPI_INT_RXUI            (1 << 2)
#define SPI_INT_RXOI            (1 << 3)
#define SPI_INT_RXFI            (1 << 4)

/* Bit fields in DMACR */
#define SPI_DMACR_TX_ENABLE     (1 << 1)
#define SPI_DMACR_RX_ENABLE     (1 << 0)

/* Bit fields in ICR */
#define SPI_CLEAR_INT_ALL       (1<< 0)
enum dw_ssi_type {
	SSI_MOTO_SPI = 0,
	SSI_TI_SSP,
	SSI_NS_MICROWIRE,
};

struct dw_spi {
	struct spi_master   *master;
	enum dw_ssi_type    type;
	u32                 regs;
	u32                 iolen;
	u32                 tx_fifo_len;    /* depth of the FIFO buffer */
	u32                 rx_fifo_len;    /* depth of the FIFO buffer */

	struct list_head    queue;
	int                 busy;
	int                 run;

	/* Current message transfer state info */
	struct spi_message  *cur_msg;
	struct spi_transfer *cur_transfer;
	struct chip_data    *cur_chip;
	struct chip_data    *prev_chip;
	size_t              len;
	u8                  *tx;
	u8                  *tx_end;
	u8                  *rx;
	u8                  *rx_end;
	u8                  n_bytes;    /* current is a 1/2 bytes op */
	u8                  max_bits_per_word;  /* maxim is 16b */
	int                 cs_change;
	int                 (*write)(struct dw_spi *dws);
	int                 (*read)(struct dw_spi *dws);
	void                (*cs_control)(struct dw_spi *dws, u32 cs, u8 flag);
};

#define dw_readl(dw, off) \
	__raw_readl(dw->regs + off)
#define dw_writel(dw,off,val) \
	__raw_writel(val, dw->regs + off)
#define dw_readw(dw, off) \
	__raw_readw(dw->regs + off)
#define dw_writew(dw,off,val) \
	__raw_writel(val, dw->regs + off)

static inline void spi_enable_chip(struct dw_spi *dws, int enable)
{
	dw_writel(dws, SPIM_ENR, (enable ? 1 : 0));
}

static inline void spi_set_clk(struct dw_spi *dws, u16 div)
{
	dw_writel(dws, SPIM_BAUDR, div);
}

/* Disable IRQ bits */
static inline void spi_mask_intr(struct dw_spi *dws, u32 mask)
{
	u32 new_mask;

	new_mask = dw_readl(dws, SPIM_IMR) & ~mask;
	dw_writel(dws, SPIM_IMR, new_mask);
}

/* Enable IRQ bits */
static inline void spi_umask_intr(struct dw_spi *dws, u32 mask)
{
	u32 new_mask;

	new_mask = dw_readl(dws, SPIM_IMR) | mask;
	dw_writel(dws, SPIM_IMR, new_mask);
}

//spi transfer mode   add by lyx
#define dw_SPI_HALF_DUPLEX 0
#define dw_SPI_FULL_DUPLEX 1

/*
 * Each SPI slave device to work with dw spi controller should
 * has such a structure claiming its working mode (PIO/DMA etc),
 * which can be save in the "controller_data" member of the
 * struct spi_device
 */
struct dw_spi_chip {
	u8 transfer_mode;/*full or half duplex*/
	u8 poll_mode;   /* 0 for contoller polling mode */
	u8 type;    /* SPI/SSP/Micrwire */
	u8 enable_dma;
	void (*cs_control)(struct dw_spi *dws, u32 cs, u8 flag);
};

#endif /* __DRIVERS_SPIM_DW_HEADER_H */
